import {CircleMarker} from './CircleMarker.js';
import {LatLngBounds} from '../../geo/LatLngBounds.js';
import {EarthCRS} from '../../geo/crs/EarthCRS.js';
/** @import {LatLngExpression} from '../../geo/LatLng.js' */
/** @import {CircleMarkerOptions} from './CircleMarker.js' */


/**
 * Options of `Circle`.
 * @typedef {object} CircleOptions
 * @property {number} [radius] Radius of the circle, in meters.
 * @extends CircleMarkerOptions
 */

/**
 * A class for drawing circle overlays on a map with radius specified in meters.
 * Extends `CircleMarker`, its `setRadius()` and `getRadius()` use meters.
 *
 * It's an approximation and starts to diverge from a real circle closer to poles
 * (due to projection distortion).
 *
 * @example
 * ```js
 * new Circle([50.5, 30.5], {radius: 200}).addTo(map);
 * ```
 */
export class Circle extends CircleMarker {

	/**
	 * Instantiates a circle object given a geographical point, and an options object
	 * which contains the circle radius.
	 * @param {LatLngExpression} latlng
	 * @param {CircleOptions} [options]
	 */
	constructor(latlng, options) {
		if (typeof options === 'number') {
			throw new Error('Circle: the radius is an option in Maplair. Use new Circle(latlng, {radius}).');
		}
		super(latlng, options);
		this.callInitHooks(Circle);
	}

	/**
	 * Returns the `LatLngBounds` of the path. When the circle isn't on a map, they're
	 * approximated on a sphere.
	 * @returns {LatLngBounds}
	 */
	getBounds() {
		if (!this._map) { return this._latlng.toBounds(this._radius * 2); }

		const half = [this._pxRadius, this._pxRadiusY ?? this._pxRadius];

		return new LatLngBounds(
			this._map.layerPointToLatLng(this._point.subtract(half)),
			this._map.layerPointToLatLng(this._point.add(half)));
	}

	_project() {

		const lng = this._latlng.lng,
		lat = this._latlng.lat,
		map = this._map,
		crs = map.options.crs,
		renderer = this._renderer,
		zoom = renderer._pathZoom;

		if (crs.distance === EarthCRS.distance) {
			const d = Math.PI / 180,
			// the radius of the CRS rather than Earth's, so it matches `map.distance()` on CRSs that set their own `R`
			latR = (this._radius / crs.R) / d,
			top = map.project([lat + latR, lng], zoom),
			bottom = map.project([lat - latR, lng], zoom),
			p = top.add(bottom).divideBy(2),
			lat2 = map.unproject(p, zoom).lat;
			// Longitude span from the haversine form of the spherical law of cosines. The plain acos() form
			// loses precision for radii of about a metre and less, where cos(latR) is too close to 1 (#6120).
			let lngR = 2 * Math.asin(Math.sqrt(
				(Math.sin(latR * d / 2) ** 2 - Math.sin((lat2 - lat) * d / 2) ** 2) /
				(Math.cos(lat * d) * Math.cos(lat2 * d)))) / d;

			if (isNaN(lngR) || lngR === 0) {
				lngR = latR / Math.cos(lat * d); // Fallback for edge case, #2425
			}

			this._point = p.subtract(renderer._pathOrigin);
			// distances rather than x/y deltas, for projections that rotate the axes
			this._pxRadius = isNaN(lngR) ? 0 : p.distanceTo(map.project([lat2, lng - lngR], zoom));
			this._pxRadiusY = p.distanceTo(top);

		} else {
			const latlng2 = crs.unproject(crs.project(this._latlng).subtract([this._radius, 0]));

			this._point = renderer._latLngToLayerPoint(this._latlng);
			this._pxRadius = Math.abs(this._point.x - renderer._latLngToLayerPoint(latlng2).x);
		}

		this._updateBounds();
	}
}
